import type { FeatureCollection, Point } from "geojson";
import { POIS_URL } from "../config";

export type PoiKind = "rozhledna" | "vrchol";

export interface PoiProps {
  /** OSM id, e.g. "osm:node/123". */
  id: string;
  name: string;
  kind: PoiKind;
  /** Elevation in metres, if mapped. */
  ele: number | null;
  municipality: string | null;
}

export type Pois = FeatureCollection<Point, PoiProps>;

/** Lookout towers and named peaks, generated by scripts/fetch-osm-pois.mjs from OpenStreetMap. */
export async function loadPois(): Promise<Pois> {
  const res = await fetch(POIS_URL);
  if (!res.ok) throw new Error(`Failed to load POIs: ${res.status}`);
  return res.json();
}

export const poiLabel = (p: PoiProps) => (p.kind === "vrchol" && p.ele !== null ? `${p.name} (${p.ele} m)` : p.name);
